//! A chunk checked against its sidecar, this build's constants and the rules: every game replayed
//! move by move to the ending it names, and a sample regenerated byte for byte.

use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

use cadence_core::chess960::dfrc_fen;
use cadence_core::generate_legal;
use cadence_core::position::Board;
use cadence_dataset::chunk::{Chunk, GameRecord, Header, chunk_name, decode_move};
use cadence_dataset::sha256::{hex, sha256};

use super::extract::{BALANCE_CAP, balance};
use super::game::{Ending, Outcome, ending};
use super::opening::{RANDOM_PLIES, SCREEN_NODES, WINDOW};
use super::packed::{self, chunk_seed};
use super::{HASH_MB, NODES, game_seed};
use crate::eval::{self, PHASE_MAX};
use crate::position::Position;
use crate::tt::Table;

/// What one chunk holds, once every check has passed.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Summary {
    pub name: String,
    pub sha256: String,
    pub header: Header,
    pub games: u64,
    pub plies: u64,
    pub kinds: [u64; 2],
    /// By start kind, in the order `Ending::word` lists them.
    pub endings: [[u64; 5]; 2],
    /// By start kind: White wins, Black wins, draws.
    pub outcomes: [[u64; 3]; 2],
    /// Every position of the game proper, by phase and by White's lead in pawns.
    pub phase: Vec<u64>,
    pub balance: Vec<u64>,
    /// Games regenerated and compared.
    pub replayed: u64,
}

/// Every check on one chunk; `replay_every` regenerates each game whose index it divides, so game 0
/// is always among them.
///
/// # Errors
///
/// The first check that fails, naming the chunk and, for a game, its index.
pub fn chunk(path: &Path, replay_every: Option<u32>, tt: &Table) -> Result<Summary, String> {
    let name = path
        .file_name()
        .map_or_else(String::new, |n| n.to_string_lossy().into_owned());
    let at = |e: String| format!("{name}: {e}");
    let bytes = fs::read(path).map_err(|e| at(e.to_string()))?;
    let digest = hex(&sha256(&bytes));
    sidecar(path, &name, &digest).map_err(at)?;
    let read = Chunk::read(&bytes).map_err(at)?;
    built_here(&read.header).map_err(at)?;
    let expected = chunk_name(read.header.run_seed, read.header.chunk_index);
    if name != expected {
        return Err(at(format!("its header names it {expected}")));
    }
    let seed = chunk_seed(read.header.run_seed, read.header.chunk_index);
    let mut summary = Summary {
        name: name.clone(),
        sha256: digest,
        header: read.header.clone(),
        games: 0,
        plies: 0,
        kinds: [0; 2],
        endings: [[0; 5]; 2],
        outcomes: [[0; 3]; 2],
        phase: vec![0; PHASE_MAX as usize + 1],
        balance: vec![0; 2 * BALANCE_CAP as usize + 1],
        replayed: 0,
    };
    for record in &read.records {
        let game = |e: String| at(format!("game {}: {e}", record.index));
        let want = game_seed(seed, u64::from(record.index));
        if record.seed != want {
            return Err(game(format!(
                "seed {:016x}, where its chunk and index give {want:016x}",
                record.seed
            )));
        }
        replay(record, &mut summary).map_err(game)?;
        if replay_every.is_some_and(|n| n > 0 && record.index.is_multiple_of(n)) {
            let again = packed::play(seed, record.index, read.header.standard_share, tt);
            let (stored, regenerated) = (
                record.encode().map_err(game)?,
                again.encode().map_err(game)?,
            );
            if stored != regenerated {
                return Err(game("does not regenerate as written".to_string()));
            }
            summary.replayed += 1;
        }
    }
    Ok(summary)
}

/// `<sha256>  <name>` as `shasum -a 256` writes it, naming this file and its bytes.
fn sidecar(path: &Path, name: &str, digest: &str) -> Result<(), String> {
    let side = PathBuf::from(format!("{}.sha256", path.display()));
    let text = fs::read_to_string(&side).map_err(|_| format!("{name}.sha256 is missing"))?;
    let want = format!("{digest}  {name}\n");
    if text != want {
        let said = text.split_whitespace().next().unwrap_or("");
        return Err(format!("SHA-256 {digest}, and its sidecar says {said}"));
    }
    Ok(())
}

/// The settings that shaped the games are this build's, and the build was a clean, known commit.
fn built_here(header: &Header) -> Result<(), String> {
    let built: [(&str, i64, i64); 5] = [
        (
            "nodes",
            header.nodes.into(),
            i64::try_from(NODES).unwrap_or(i64::MAX),
        ),
        (
            "screen nodes",
            header.screen_nodes.into(),
            i64::try_from(SCREEN_NODES).unwrap_or(i64::MAX),
        ),
        (
            "hash",
            header.hash_mb.into(),
            i64::try_from(HASH_MB).unwrap_or(i64::MAX),
        ),
        (
            "random plies",
            header.random_plies.into(),
            i64::try_from(RANDOM_PLIES).unwrap_or(i64::MAX),
        ),
        ("window", header.window.into(), WINDOW.into()),
    ];
    for (field, named, here) in built {
        if named != here {
            return Err(format!(
                "the header names {field} {named} and this build's is {here}"
            ));
        }
    }
    if header.standard_share > 100 {
        return Err(format!(
            "the header names a standard share of {}",
            header.standard_share
        ));
    }
    if header.net_sha256 != [0; 32] {
        return Err(
            "the header names a network, and the handcrafted evaluation has none".to_string(),
        );
    }
    if header.commit == [0; 20] {
        return Err("the header names no commit".to_string());
    }
    if header.modified != 0 {
        return Err("the header says a modified tree built it".to_string());
    }
    Ok(())
}

/// Every random ply and move legal from the record's start, no ending before the last move, and the
/// ending recomputed equal to the one stored.
fn replay(record: &GameRecord, summary: &mut Summary) -> Result<(), String> {
    let fen = dfrc_fen(u32::from(record.white), u32::from(record.black));
    let mut board = Position::new(Board::from_fen(&fen).map_err(|e| format!("{fen}: {e:?}"))?);
    for &bits in &record.plies {
        let m = decode_move(&generate_legal(&board), bits)
            .ok_or_else(|| format!("random ply {bits:#06x} is not legal"))?;
        board.play(m);
    }
    for &(bits, _) in &record.moves {
        if let Some((end, _)) = ending(&board) {
            return Err(format!("a move after the game ended by {}", end.word()));
        }
        let pawns = balance(&board).clamp(-BALANCE_CAP, BALANCE_CAP) + BALANCE_CAP;
        summary.phase[eval::phase(&board) as usize] += 1;
        summary.balance[pawns as usize] += 1;
        let m = decode_move(&generate_legal(&board), bits)
            .ok_or_else(|| format!("move {bits:#06x} is not legal"))?;
        board.play(m);
    }
    let found = ending(&board).ok_or("the moves do not end the game")?;
    let stored = (
        stored_ending(record.ending)?,
        stored_outcome(record.outcome)?,
    );
    if found != stored {
        return Err(format!(
            "the moves end {} {} and the record says {} {}",
            found.1.text(),
            found.0.word(),
            stored.1.text(),
            stored.0.word()
        ));
    }
    let kind = usize::from(record.kind);
    summary.games += 1;
    summary.plies += record.moves.len() as u64;
    summary.kinds[kind] += 1;
    summary.endings[kind][usize::from(record.ending)] += 1;
    summary.outcomes[kind][usize::from(record.outcome)] += 1;
    Ok(())
}

fn stored_ending(code: u8) -> Result<Ending, String> {
    Ok(match code {
        0 => Ending::Mate,
        1 => Ending::Stalemate,
        2 => Ending::Repetition,
        3 => Ending::FiftyMoves,
        4 => Ending::InsufficientMaterial,
        _ => return Err(format!("ending {code}")),
    })
}

fn stored_outcome(code: u8) -> Result<Outcome, String> {
    Ok(match code {
        0 => Outcome::White,
        1 => Outcome::Black,
        2 => Outcome::Draw,
        _ => return Err(format!("outcome {code}")),
    })
}

/// The `.cdg` files a path names: itself, or every one in it in name order.
///
/// # Errors
///
/// A path that cannot be read.
pub fn chunk_paths(path: &Path) -> Result<Vec<PathBuf>, String> {
    if !path.is_dir() {
        return Ok(vec![path.to_path_buf()]);
    }
    let mut paths = Vec::new();
    for entry in fs::read_dir(path).map_err(|e| format!("{}: {e}", path.display()))? {
        let entry = entry.map_err(|e| e.to_string())?.path();
        if entry.extension().is_some_and(|e| e == "cdg") {
            paths.push(entry);
        }
    }
    paths.sort();
    Ok(paths)
}

/// One dataset's source manifest: the settings every chunk shares, then a row per chunk.
///
/// # Errors
///
/// Chunks that disagree about their commit, version or settings, which are not one dataset.
pub fn manifest(summaries: &[Summary]) -> Result<String, String> {
    let first = summaries.first().ok_or("no chunk to list")?;
    let settings = |h: &Header| {
        (
            h.commit,
            h.version.clone(),
            h.nodes,
            h.screen_nodes,
            h.hash_mb,
            h.random_plies,
            h.window,
            h.standard_share,
        )
    };
    if let Some(other) = summaries
        .iter()
        .find(|s| settings(&s.header) != settings(&first.header))
    {
        return Err(format!(
            "{} and {} were written by different builds or settings",
            first.name, other.name
        ));
    }
    let h = &first.header;
    let mut seeds: Vec<String> = summaries
        .iter()
        .map(|s| format!("{:016x}", s.header.run_seed))
        .collect();
    seeds.dedup();
    let mut text = String::new();
    let _ = writeln!(
        text,
        "# cadence dataset manifest, written by datagen verify --manifest"
    );
    let _ = writeln!(text, "commit\t{}", hex(&h.commit));
    let _ = writeln!(text, "version\t{}", h.version);
    let _ = writeln!(
        text,
        "nodes\t{}\nscreen-nodes\t{}\nhash\t{}",
        h.nodes, h.screen_nodes, h.hash_mb
    );
    let _ = writeln!(
        text,
        "random-plies\t{}\nwindow\t{}\nstandard-share\t{}",
        h.random_plies, h.window, h.standard_share
    );
    let _ = writeln!(text, "run-seeds\t{}", seeds.join(" "));
    let _ = writeln!(text, "chunk\tsha256\tgames\tplies\tuniform\tstandard");
    for s in summaries {
        let _ = writeln!(
            text,
            "{}\t{}\t{}\t{}\t{}\t{}",
            s.name, s.sha256, s.games, s.plies, s.kinds[0], s.kinds[1]
        );
    }
    Ok(text)
}

/// Counts by start kind, endings and outcomes, then phase and balance over every position.
#[must_use]
#[expect(
    clippy::cast_precision_loss,
    reason = "a position count is far below 2^52"
)]
pub fn report(summaries: &[Summary]) -> String {
    let mut text = String::new();
    let (mut kinds, mut endings, mut outcomes) = ([0_u64; 2], [[0_u64; 5]; 2], [[0_u64; 3]; 2]);
    let mut phase = vec![0_u64; PHASE_MAX as usize + 1];
    let mut lead = vec![0_u64; 2 * BALANCE_CAP as usize + 1];
    let (mut games, mut plies, mut replayed) = (0, 0, 0);
    for s in summaries {
        games += s.games;
        plies += s.plies;
        replayed += s.replayed;
        for k in 0..2 {
            kinds[k] += s.kinds[k];
            for (all, n) in endings[k].iter_mut().zip(s.endings[k]) {
                *all += n;
            }
            for (all, n) in outcomes[k].iter_mut().zip(s.outcomes[k]) {
                *all += n;
            }
        }
        for (all, n) in phase.iter_mut().zip(&s.phase) {
            *all += n;
        }
        for (all, n) in lead.iter_mut().zip(&s.balance) {
            *all += n;
        }
    }
    let _ = writeln!(
        text,
        "chunks {} games {games} plies {plies} replayed {replayed}",
        summaries.len()
    );
    for (k, kind) in ["uniform", "standard"].iter().enumerate() {
        let (e, o) = (endings[k], outcomes[k]);
        let _ = writeln!(
            text,
            "{kind} games {} endings mate {} stalemate {} repetition {} fifty {} material {} \
             outcomes white {} black {} draw {}",
            kinds[k], e[0], e[1], e[2], e[3], e[4], o[0], o[1], o[2]
        );
    }
    let positions: u64 = phase.iter().sum();
    let share = |n: u64| 100.0 * n as f64 / positions.max(1) as f64;
    let _ = writeln!(
        text,
        "phase (0 bare, {PHASE_MAX} full), every position of the game proper"
    );
    for (p, &n) in phase.iter().enumerate() {
        let _ = writeln!(text, "  {p:>3} {n:>10} {:>6.2}%", share(n));
    }
    let _ = writeln!(text, "balance (White's lead in pawns)");
    for (i, &n) in lead.iter().enumerate() {
        let pawns = i32::try_from(i).unwrap_or(i32::MAX) - BALANCE_CAP;
        let _ = writeln!(text, "  {pawns:>+3} {n:>10} {:>6.2}%", share(n));
    }
    text
}
